var EXTRA=[{"dot": "green", "j": "Arthroscopy", "h": "Crociato posteriore: la sede della rottura alla risonanza guida il trattamento", "v": "Commento editoriale a una classificazione per sede su risonanza; fra i predittori di rottura prossimale compaiono lesione multilegamentosa e menisco mediale rotto. Non porta dati nuovi.", "pmid": "42949134", "doi": "10.1002/arj.70701", "temi": ["crociato posteriore", "multilegamentose", "risonanza"]}, {"dot": "green", "j": "Knee Surg Sports Traumatol Arthrosc", "h": "Fratture del piatto posterolaterale nel LCA: la sola presenza non basta", "v": "Lettera in risposta a uno studio prospettico: distingue le impressioni corticali dai difetti profondi e ricorda che il pivot-shift preoperatorio misura solo in parte l'instabilità.", "pmid": "42949176", "doi": "10.1002/ksa.70662", "temi": ["LCA", "piatto tibiale", "pivot-shift", "slope"]}, {"dot": "gray", "j": "Knee Surg Sports Traumatol Arthrosc", "h": "Rientro ritardato dopo debridement del corpo adiposo: effetto chirurgico o fenotipo?", "v": "Lettera a una metanalisi sulla tendinopatia rotulea: il ritardo potrebbe indicare un dolore anteriore più irritabile e un carico da ricostruire, non solo la chirurgia.", "pmid": "42949220", "doi": "10.1002/ksa.70663", "temi": ["tendinopatia rotulea", "rientro allo sport", "corpo adiposo"]}, {"dot": "gray", "j": "J Arthroplasty", "h": "Protesi di revisione asettica: chi viene rivisto per instabilità fallisce presto", "v": "Serie monocentrica a lungo termine; instabilità, perdita ossea grave e revisioni precedenti predicono una nuova revisione, ma non sono confermate nelle prime revisioni.", "pmid": "42950899", "doi": "10.1016/j.arth.2026.10.028", "temi": ["revisione protesica", "instabilità", "sopravvivenza"]}, {"dot": "gray", "j": "J Clin Med", "h": "Protesi robotica ROSA: il bilanciamento mediolaterale è riproducibile fra chirurghi", "v": "Studio osservazionale con due chirurghi; buona concordanza in estensione e flessione precoce, più debole in flessione profonda.", "pmid": "42941440", "doi": "10.3390/jcm15207926", "temi": ["protesi robotica", "bilanciamento", "ROSA"]}, {"dot": "gray", "j": "J Biomech", "h": "Protesi non cementata con allineamento cinematico: il varo nativo non altera la fissazione", "v": "Studio computazionale a elementi finiti su modelli di pazienti; nessun operato, quindi nessun dato clinico.", "pmid": "42950574", "doi": "10.1016/j.jbiomech.2026.113637", "temi": ["protesi non cementata", "allineamento cinematico", "elementi finiti"]}, {"dot": "gray", "j": "Medicina (Kaunas)", "h": "Due protesi non cementate a crociato conservato: revisioni precoci rare, senza differenza dimostrata", "v": "Coorte retrospettiva appaiata con pochissimi eventi; l'assenza di differenza non prova equivalenza.", "pmid": "42942450", "doi": "10.3390/medicina62101919", "temi": ["protesi non cementata", "revisione", "confronto fra impianti"]}, {"dot": "gray", "j": "Injury", "h": "Sci: i costi di ricovero sono sottostimati perché mancano le lesioni del ginocchio", "v": "Lettera; l'abstract non è disponibile, quindi metodo e dati non sono noti.", "pmid": "42946597", "doi": "10.1016/j.injury.2026.113832", "temi": ["sci", "lesioni del ginocchio", "epidemiologia"]}, {"dot": "gray", "j": "J Biomech", "h": "Un'indicazione verbale sul piede riduce il carico in valgo nel cambio di direzione", "v": "Esperimento di laboratorio su giovani atlete universitarie con effetto immediato; non misura infortuni né durata dell'effetto.", "pmid": "42950569", "doi": "10.1016/j.jbiomech.2026.113638", "temi": ["LCA", "prevenzione", "valgismo dinamico", "atlete"]}, {"dot": "gray", "j": "BMC Sports Sci Med Rehabil", "h": "Dopo LCA, allenamento neurocognitivo con occhiali stroboscopici: miglior prestazione al salto in doppio compito", "v": "RCT molto piccolo su atleti maschi con test funzionale e kinesiofobia; non misura rirotture né rientro.", "pmid": "42947260", "doi": "10.1186/s13102-026-01932-1", "temi": ["LCA", "riabilitazione", "stroboscopio", "kinesiofobia"]}, {"dot": "gray", "j": "J Orthop Surg Res", "h": "Dopo LCA nelle atlete: allenamento neuromuscolare e visuo-motorio migliorano l'atterraggio", "v": "RCT a tre gruppi con esiti di laboratorio e di prontezza psicologica; follow-up breve.", "pmid": "42947231", "doi": "10.1186/s13018-026-07141-3", "temi": ["LCA", "atlete", "atterraggio", "ACL-RSI"]}, {"dot": "gray", "j": "Eur J Orthop Surg Traumatol", "h": "Acido tranexamico topico o endovenoso nella protesi: nessuna differenza dimostrata", "v": "Metanalisi di RCT con intervalli ampi e dati di sicurezza incompleti: non prova equivalenza.", "pmid": "42944926", "doi": "10.1007/s00590-026-05013-4", "temi": ["protesi totale", "sanguinamento", "acido tranexamico"]}];
var SCOPERTE=[{"t": "Terapia a fuoco sui meridiani contro celecoxib nell'artrosi iniziale: protocollo di un RCT cinese", "v": "È il protocollo di un trial non ancora concluso, quindi nessun risultato e nessuna prova di efficacia. Vale la deviazione perché mostra come la medicina tradizionale cinese disegna un confronto con un farmaco e con biomarcatori, un campo poco frequentato dalla letteratura occidentale.", "pmid": "42936697", "doi": "10.2147/JPR.S561198", "temi": ["medicina tradizionale cinese", "artrosi", "RCT", "biomarcatori"]}, {"t": "Sintetizzare con apprendimento profondo contrasti RM del ginocchio da un'unica acquisizione quantitativa", "v": "Studio trasversale su volontari con sintomi al ginocchio (Oulu): le immagini sintetiche hanno una qualità un po' inferiore e non permettono di valutare la sinovite. Vale la deviazione per capire dove l'intelligenza artificiale accorcia la risonanza e dove ancora no.", "pmid": "42944948", "doi": "10.1007/s10334-026-01432-w", "temi": ["intelligenza artificiale", "risonanza magnetica", "sinovite", "imaging quantitativo"]}, {"t": "Seguire con PET e SPECT le cellule staminali iniettate nell'artrosi del ginocchio", "v": "Rassegna su come marcare le cellule e vederle nel tempo: radiotossicità, perdita del tracciante e precisione della quantificazione sono i limiti dichiarati. Vale la deviazione per le terapie cellulari dell'asse ICRS, perché il tracciamento è il punto tecnico su cui poggia ogni lettura dell'effetto.", "pmid": "42949170", "doi": "10.3791/71882", "temi": ["cellule staminali", "PET", "imaging", "terapie cellulari"]}];
var SOC={"1": {"video": "Dopo il crociato, chi torna allo sport come prima si sente anche più pronto: lo mostra una revisione di 25 studi su 7174 operati. Torna allo sport il 79,3%, al livello di prima il 44,1%; la distanza nella fiducia nel ginocchio fra chi rientra del tutto e chi no cresce col tempo, quella nei test di forza e di salto resta di pochi punti percentuali.\n\nIl limite: sono studi osservazionali, mostrano un'associazione e non la causa.\nFonte: PubMed, PMID 42951020.", "linkedin": "Rientro dopo LCA e prontezza psicologica (J Sport Health Sci, 2026): revisione sistematica con metanalisi, 25 studi, 7174 operati. Rientro allo sport 79,3%, al livello pre-infortunio 44,1%. Differenza di ACL-RSI fra chi rientra al livello pre-infortunio e chi no 16,09 (IC 95% 9,13-23,05) a 6 mesi o meno, 27,07 (22,37-31,76) oltre i 12; differenze di LSI di circa 3-7 punti percentuali.\n\nIl limite: studi osservazionali, innesto e LET non riportati nell'abstract.\nFonte: PubMed, PMID 42951020.", "instagram": "Dopo il crociato conta anche sentirsi pronti, non solo la forza.\n\nIn 25 studi su 7174 operati, chi torna al livello di prima si sente più sicuro del ginocchio, e la distanza cresce nei mesi. Studi osservazionali.\nFonte: PubMed, PMID 42951020.", "pazienti": "Una revisione di 25 studi su oltre 7000 persone operate di crociato mostra che chi torna al livello di sport di prima si dichiara più sicuro del proprio ginocchio, e la differenza aumenta nei mesi; nei test di forza le differenze sono piccole.\n\nSono osservazioni, non provano la causa. Quando riprendere lo sport si decide caso per caso.\nFonte: PubMed, PMID 42951020."}};
var SOCV={"1": {"video": {"chir": ["Prontezza psicologica e rientro dopo LCA (J Sport Health Sci, 2026): revisione sistematica con metanalisi, 25 studi, 7174 operati. Rientro allo sport 79,3%, rientro al livello pre-infortunio 44,1%.", "La differenza di ACL-RSI fra chi torna al livello pre-infortunio e chi no cresce nel tempo, 16,09 punti (IC 95% 9,13-23,05) entro 6 mesi e 27,07 (22,37-31,76) oltre i 12. Le differenze di LSI fra rientrati e non sono di circa 3-7 punti percentuali.", "Il limite: studi osservazionali, associazione e non previsione; innesto e LET non riportati nell'abstract, quindi nessuna lettura per il quadricipite con Lemaire. Solo abstract.\nFonte: PubMed, PMID 42951020."], "misto": ["Dopo il crociato, chi torna allo sport come prima si sente anche più pronto: lo mostra una revisione di 25 studi su 7174 operati.", "Torna allo sport il 79,3%, al livello di prima il 44,1%. La distanza nella fiducia nel ginocchio fra chi rientra del tutto e chi no cresce col tempo; quella nei test di forza e di salto resta di pochi punti percentuali.", "Il limite: sono studi osservazionali, mostrano un'associazione e non dicono che cosa causa il rientro; il tipo di innesto non è riportato nell'abstract.\nFonte: PubMed, PMID 42951020."], "pazienti": ["Dopo un'operazione al crociato, tornare allo sport dipende anche da quanto ci si sente pronti, non solo dalla forza.", "Una revisione di 25 studi su oltre 7000 persone: circa otto su dieci tornano allo sport e circa quattro su dieci al livello di prima. Chi torna al livello di prima si dichiara più sicuro del proprio ginocchio, e la differenza aumenta nei mesi.", "Sono studi che osservano, non provano che la fiducia faccia tornare allo sport. Quando riprendere si decide con il chirurgo e il fisioterapista.\nFonte: PubMed, PMID 42951020."]}, "linkedin": {"chir": ["Rientro dopo LCA e prontezza psicologica (J Sport Health Sci, 2026): revisione sistematica con metanalisi, 25 studi, 7174 operati. Rientro allo sport 79,3%, al livello pre-infortunio 44,1%. Differenza di ACL-RSI fra chi rientra al livello pre-infortunio e chi no 16,09 (IC 95% 9,13-23,05) a 6 mesi o meno, 27,07 (22,37-31,76) oltre i 12.", "Fra rientrati e non, IKDC 7,52 (5,85-9,19), sotto la soglia minima rilevante; LSI di estensione 7,48% (2,69-12,26), di flessione 3,67% (0,91-6,43), salto monopodalico 2,96% (1,77-4,16).", "Il limite: studi osservazionali, associazione e non previsione; definizioni di rientro eterogenee; innesto e LET non riportati nell'abstract. Solo abstract.\nFonte: PubMed, PMID 42951020."], "misto": ["Rientro allo sport dopo il crociato: quanto conta sentirsi pronti? Una revisione di 25 studi su 7174 operati mostra che chi torna al livello di prima ha punteggi di fiducia nel ginocchio (ACL-RSI) più alti di chi non ci torna, e la distanza cresce nei mesi.", "Le differenze nei test di forza e di salto sono più piccole, di pochi punti percentuali. Torna allo sport il 79,3%, al livello di prima il 44,1%.", "Il limite: sono studi osservazionali e non dimostrano la causa; il tipo di innesto non è riportato nell'abstract.\nFonte: PubMed, PMID 42951020."], "pazienti": ["Dopo l'operazione al crociato la fiducia nel ginocchio conta quanto la forza: lo suggerisce una revisione di 25 studi su oltre 7000 persone.", "Chi riesce a tornare al livello di sport di prima si dichiara più sicuro del ginocchio, e la differenza con gli altri aumenta col passare dei mesi; nei test di forza e di salto le differenze sono piccole.", "Gli studi osservano un'associazione e non possono dire che cosa viene prima. Quando riprendere lo sport si decide caso per caso.\nFonte: PubMed, PMID 42951020."]}, "instagram": {"chir": ["Dopo LCA, la prontezza psicologica distingue i rientrati più dei test di forza? In 25 studi e 7174 operati la distanza di ACL-RSI cresce nel tempo, da 16,09 a 27,07 punti.", "Differenze di LSI di circa 3-7 punti percentuali. Rientro al livello pre-infortunio 44,1%.", "Studi osservazionali, innesto non riportato.\nFonte: PubMed, PMID 42951020."], "misto": ["Dopo il crociato conta anche sentirsi pronti, non solo la forza.", "In 25 studi su 7174 operati, chi torna al livello di prima si sente più sicuro del ginocchio, e la distanza cresce nei mesi.", "Studi osservazionali.\nFonte: PubMed, PMID 42951020."], "pazienti": ["Tornare allo sport dopo il crociato: contano anche fiducia e sicurezza.", "Una revisione di 25 studi su oltre 7000 persone: chi si sente più sicuro del ginocchio torna più spesso al livello di prima.", "Sono osservazioni, non prove di causa.\nFonte: PubMed, PMID 42951020."]}, "reel": {"chir": ["[Testo a schermo] ACL-RSI e rientro dopo LCA", "25 studi, 7174 operati.", "Osservazionale, innesto non riportato.\nFonte: PubMed, PMID 42951020."], "misto": ["[Testo a schermo] Dopo il crociato conta sentirsi pronti", "La differenza cresce nei mesi.", "Studi osservazionali.\nFonte: PubMed, PMID 42951020."], "pazienti": ["[Testo a schermo] Tornare allo sport: la fiducia conta", "Contano forza e sicurezza.", "Sono osservazioni, non prove.\nFonte: PubMed, PMID 42951020."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LCA #Ginocchio", "instagram": "#ortopedia #ginocchio #crociateanteriore #lca #ritornoallosport #riabilitazione #chirurgiadelginocchio #medicinabasatasulleprove #ortopediaticino #ticino #salute", "kw": "crociato anteriore, ritorno allo sport, prontezza psicologica, riabilitazione, chirurgia del ginocchio, ginocchio, ortopedia"}};
var NLB={"1": {"prof": ["Dopo LCA la prontezza psicologica distingue i rientrati più dei test di forza (25 studi, 7174 operati)", "Revisione sistematica con metanalisi (J Sport Health Sci, 2026; solo abstract): rientro allo sport 79,3%, al livello pre-infortunio 44,1%. Differenza di ACL-RSI fra chi rientra al livello pre-infortunio e chi no 16,09 (IC 95% 9,13-23,05) entro 6 mesi e 27,07 (22,37-31,76) oltre i 12; differenze di LSI da 3 a 7 punti percentuali.", "Nota critica: studi osservazionali, associazione e non previsione; definizioni di rientro eterogenee; innesto e LET non riportati nell'abstract."], "mix": ["Dopo il crociato conta sentirsi pronti: la differenza cresce nei mesi, quella nei test di forza resta piccola", "Una revisione di 25 studi su 7174 persone operate di crociato mostra che chi torna al livello di sport di prima ha punteggi di fiducia nel ginocchio (ACL-RSI) più alti di chi non ci torna, con una distanza che aumenta col tempo, mentre nei test di forza e di salto le differenze sono di pochi punti percentuali. Torna allo sport il 79,3%, al livello di prima il 44,1%.", "Nota sul limite: sono studi che osservano e non provano la causa; l'abstract non dice quale innesto sia stato usato."], "paz": ["Dopo l'operazione al crociato, tornare allo sport dipende anche da quanto ci si sente sicuri del ginocchio", "Una revisione di 25 studi su oltre 7000 persone operate di crociato: circa otto su dieci tornano allo sport e circa quattro su dieci al livello di prima. Chi torna al livello di prima si dichiara più sicuro del proprio ginocchio, e la differenza con gli altri aumenta nei mesi; nei test di forza le differenze sono piccole.", "Nota rassicurante: sono osservazioni, non provano che la fiducia faccia tornare allo sport; quando riprendere si decide con il chirurgo e il fisioterapista, caso per caso."], "kw": "crociato anteriore, ritorno allo sport, riabilitazione del ginocchio, fiducia nel ginocchio"}, "2": {"prof": ["Radice mediale transtibiale con due lasso-loop e nodo SMC su bottone tibiale: nota tecnica senza pazienti", "Nota tecnica con video (Arthrosc Tech, 2026; testo completo letto): pull-out transtibiale della radice posteriore mediale con due suture lasso-loop, nodo scorrevole Samsung Medical Center e bottone corticale tibiale da 16 mm su un tunnel da 4,0 mm. Nessun dato clinico o biomeccanico.", "Nota critica: nessun paziente e nessuna misura di tenuta; gli autori ammettono che non corregge l'estrusione persistente."], "mix": ["Riparare la radice del menisco con un solo tunnel: una variante tecnica descritta, non ancora provata", "Da Ankara arriva la descrizione di una variante per riparare la radice posteriore del menisco interno: tre suture passate attraverso un solo tunnel nella tibia e fissate su un bottone sull'osso, con un nodo scorrevole per regolare la tensione. È un testo con video, senza pazienti e senza risultati.", "Nota sul limite: la solidità della fissazione è un giudizio degli autori, senza misure; loro stessi scrivono che non corregge lo spostamento del menisco nei casi cronici."], "paz": ["Menisco interno: descritta una variante di riparazione della radice, senza risultati sui pazienti", "Chirurghi di Ankara hanno descritto, con un video, come riparare la radice del menisco interno, cioè il punto in cui il menisco si ancora all'osso, usando tre suture e un solo tunnel nella tibia. Non vengono riportati pazienti né risultati.", "Nota rassicurante: è una descrizione tecnica fra le tante; la scelta di come riparare il menisco spetta al chirurgo in base al caso."], "kw": "menisco interno, radice meniscale, sutura del menisco, chirurgia artroscopica"}, "3": {"prof": ["HTO di apertura con guide personalizzate: torsione tibiale invariata, slope variabile con la frattura della cerniera", "Coorte retrospettiva (J Exp Orthop, 2026; solo abstract): 118 ginocchia, frattura della cerniera in 52 (44,1%). Torsione tibiale 25,1° ± 8,5° prima e 25,0° ± 8,6° dopo (p=0,727), invariata anche con frattura (p=0,803); variazione di slope 2,0° ± 2,6° con frattura contro 0,3° ± 1,9° senza (p<0,001).", "Nota critica: retrospettivo, senza confronto con la tecnica convenzionale e senza esiti clinici; l'effetto della frattura non si separa da quello della correzione più ampia."], "mix": ["Osteotomia della tibia con guide su misura: la rotazione dell'osso non cambia, l'inclinazione sì", "In 118 ginocchia operate a Zurigo di osteotomia tibiale di apertura con guide personalizzate, la rotazione della tibia è rimasta invariata, anche nelle 52 in cui si è fratturata la cerniera ossea. L'inclinazione del piatto tibiale all'indietro (slope) è variata di circa 2° quando c'era la frattura, contro 0,3° quando non c'era.", "Nota sul limite: lo studio guarda indietro nel tempo, non confronta con la tecnica abituale e non riporta come stavano i pazienti."], "paz": ["Osteotomia per il ginocchio: uno studio guarda se la tibia ruota dopo l'intervento", "Chirurghi di Zurigo hanno misurato, su 118 ginocchia operate di osteotomia con guide personalizzate, se la rotazione della tibia cambiasse dopo l'intervento: non è cambiata, anche quando una piccola parte dell'osso a cerniera si era incrinata. L'inclinazione del piatto è invece variata un po' di più in questi casi.", "Nota rassicurante: lo studio riguarda misure radiologiche e non dice come stessero i pazienti; l'intervento si discute con il chirurgo caso per caso."], "kw": "osteotomia tibiale, ginocchio varo, artrosi del ginocchio, chirurgia conservativa"}, "4": {"prof": ["Osteotomia a doppio livello: a 24 mesi il 56,9% recupera il Tegner di cinque anni prima, l'88,2% quello preoperatorio", "Coorte retrospettiva (OTSR, 2026; solo abstract): 51 pazienti. Tegner mediano 5 cinque anni prima, 3 prima dell'intervento, 4 a 24 mesi. Una PCS più alta si associa al mancato recupero del livello di cinque anni prima (OR 1,066 per punto; IC 95% 1,008-1,143; p=0,025), analisi esplorativa.", "Nota critica: livello presintomatico richiamato a memoria, pazienti selezionati, nessun confronto, analisi esplorativa."], "mix": ["Osteotomia a doppio livello e sport: tornare al livello di prima è più difficile di quanto sembri", "A due anni da un'osteotomia a doppio livello per artrosi, circa 57 pazienti su 100 sono tornati al livello di attività che avevano cinque anni prima, mentre circa 88 su 100 sono tornati al livello che avevano appena prima dell'intervento, già ridotto dal dolore. Chi aveva più paura e catastrofismo del dolore ha recuperato meno, in un'analisi esplorativa.", "Nota sul limite: il livello di cinque anni prima è ricordato a memoria e lo studio riguarda 51 persone selezionate, senza confronto."], "paz": ["Dopo un'osteotomia del ginocchio, quanto sport si recupera? Il punto di riferimento conta", "Uno studio giapponese su 51 persone operate di osteotomia a doppio livello ha chiesto quale livello di attività avessero cinque anni prima del dolore. A due anni poco più della metà era tornata a quel livello, quasi tutte a quello che avevano appena prima dell'operazione.", "Nota rassicurante: è un piccolo studio e il ricordo di cinque anni prima può essere impreciso; il recupero si discute caso per caso con il chirurgo."], "kw": "osteotomia del ginocchio, ritorno allo sport, artrosi del ginocchio, doppio livello"}, "5": {"prof": ["Protesi totale robotica con ROSA e allineamento funzionale: 178 ginocchia su 180 in classe REAL 1A", "Studio retrospettivo (Musculoskelet Surg, 2026; solo abstract): 180 ginocchia, bilanciamento sul compartimento non usurato con spazio di 19 mm. Classe REAL 1A nel 98,9% (IC 95% 96,0-99,7, calcolo mio), rilasci dei tessuti molli nel 7,8%, nessuna instabilità intraoperatoria.", "Nota critica: nessun confronto, nessun esito clinico, misura della laschezza fatta dal robot; piattaforma ROSA, non VELYS."], "mix": ["Protesi di ginocchio con robot: bilanciare sul lato meno consumato dà simmetria a fine intervento", "In 180 ginocchia operate a Milano di protesi totale con un robot senza immagini preoperatorie, i chirurghi hanno regolato il bilanciamento dei legamenti prendendo come riferimento il lato meno consumato dall'artrosi. A fine intervento il 98,9% dei ginocchi aveva legamenti simmetrici tra lato interno ed esterno, e in 14 casi sono serviti rilasci dei tessuti molli.", "Nota sul limite: la misura è intraoperatoria, senza confronto con altri metodi e senza notizie sul decorso dei pazienti."], "paz": ["Protesi di ginocchio con il robot: uno studio sul bilanciamento dei legamenti durante l'intervento", "Un gruppo di Milano ha usato un robot per misurare la tensione dei legamenti durante 180 interventi di protesi totale di ginocchio. A fine intervento, quasi tutti avevano una tensione simile tra lato interno ed esterno del ginocchio.", "Nota rassicurante: lo studio misura ciò che accade in sala operatoria, non il decorso dopo l'intervento; la scelta della tecnica spetta al chirurgo."], "kw": "protesi di ginocchio, chirurgia robotica, protesi totale, artrosi del ginocchio"}, "6": {"prof": ["Cartilagine del ginocchio, NSQIP 2010-2023: ACI e allotrapianti in aumento, complicanze fra 1,5% e 3,7%", "Studio su database (Arthrosc Sports Med Rehabil, 2026; solo abstract): 23.190 pazienti. Aumento d'uso di ACI e allotrapianti (p<0,001) e di autotrapianto artroscopico (p=0,011); complicanze dall'1,54% (microfratture) al 3,74% (allotrapianto aperto). Condroplastica RR 1,44 (IC 95% 1,13-1,83) e autotrapianto artroscopico RR 2,33 (1,37-3,95) rispetto alle microfratture.", "Nota critica: database senza esiti clinici, codici che non distinguono AMIC o cartilagine particellata, indicazioni diverse fra tecniche."], "mix": ["Cartilagine del ginocchio negli Stati Uniti: si ricostruisce di più e le complicanze restano rare", "In un grande database americano, fra 23.190 operati per lesioni della cartilagine del ginocchio gli interventi di ricostruzione (impianto di cellule, trapianti di cartilagine e osso) sono aumentati negli anni. Le complicanze sono rimaste basse in tutte le tecniche, da circa 1,5% a circa 3,7%.", "Nota sul limite: il database registra le complicanze, non il dolore né la funzione, e le tecniche non sono confrontabili tra loro perché si usano in casi diversi."], "paz": ["Lesioni della cartilagine del ginocchio: negli Stati Uniti si usano di più le tecniche di ricostruzione", "Uno studio su oltre 23.000 operati americani mostra che le tecniche che ricostruiscono la cartilagine sono usate sempre più spesso e che le complicanze dell'intervento sono poco frequenti, con differenze piccole fra le varie tecniche.", "Nota rassicurante: lo studio non dice quale tecnica funzioni meglio; la scelta dipende dal tipo di lesione e si discute con il chirurgo."], "kw": "cartilagine del ginocchio, lesione cartilaginea, trapianto di cartilagine, chirurgia del ginocchio"}, "7": {"prof": ["PRP nell'artrosi K-L I-II: percorso standardizzato contro PRP abituale, VAS −2,98 a 12 mesi (240 pazienti)", "RCT in doppio cieco (Am J Sports Med, 2026; solo abstract): VAS −2,98 (IC 95% da −3,64 a −2,32), WOMAC −8,63 (da −11,35 a −5,90), IKDC 10,25 (8,37-12,13); eventi avversi 14,8% contro 31,9% (RR 0,46; IC 95% 0,28-0,78, calcolo mio).", "Nota critica: nessun placebo, componenti del percorso raggruppate; lo studio non stabilisce l'efficacia del PRP."], "mix": ["PRP per l'artrosi iniziale: fare meglio il percorso conta, ma non dimostra che il PRP funzioni", "In uno studio su 240 persone con artrosi lieve del ginocchio, un percorso standardizzato di infiltrazioni di PRP (selezione, preparazione controllata, ecoguida, riabilitazione e controlli) ha dato a un anno meno dolore e una funzione maggiore rispetto alla pratica abituale, con meno effetti indesiderati: 14,8% contro 31,9%.", "Nota sul limite: manca un gruppo placebo e le parti del percorso sono insieme, quindi non si sa se conti il PRP o l'organizzazione."], "paz": ["Artrosi lieve del ginocchio: uno studio confronta due modi di organizzare le infiltrazioni di PRP", "In 240 persone con artrosi lieve, chi ha seguito un percorso organizzato di infiltrazioni con controlli e riabilitazione stava meglio a un anno rispetto a chi ha ricevuto le infiltrazioni nel modo abituale, con meno effetti indesiderati.", "Nota rassicurante: lo studio non dice se il PRP in sé funzioni, perché non c'era un gruppo senza trattamento; la scelta si discute con il medico."], "kw": "artrosi del ginocchio, PRP, infiltrazioni, plasma ricco di piastrine"}};
var ARTICLES=[{n:1,mono:'m-gray',dot:'green',sec:'res',j:'J Sport Health Sci',h:'Dopo LCA, la distanza nella prontezza psicologica fra chi rientra al livello di prima e chi no cresce nel tempo; quella nei test funzionali resta piccola',v:'Revisione sistematica con metanalisi di 25 studi e 7174 operati di LCA (ricerca fino ad aprile 2026): rientro allo sport 79,3%, rientro al livello pre-infortunio 44,1%. La differenza di ACL-RSI fra chi torna al livello pre-infortunio e chi no passa da 16,09 punti (IC 95% 9,13-23,05) entro 6 mesi a 18,64 (14,64-22,63) fra 6 e 12 mesi e 27,07 (22,37-31,76) oltre i 12 mesi; le differenze di LSI fra rientrati e non restano di pochi punti percentuali.',ax:'Jiang, Zhong, Tu, Xu, Liu, Wang, Wang, Dai',date:'ott 2026',meta:'revisione sistematica con metanalisi, 25 studi, 7174 pazienti, solo abstract',pmid:'42951020',doi:'10.1016/j.jshs.2026.101188',journal:'Journal of sport and health science',authors:'Jiang J, Zhong Y, Tu X, Xu G, Liu Y, Wang S, Wang L, Dai X',design:'Revisione sistematica con metanalisi (PRISMA; PROSPERO CRD42025630743): sei banche dati dal 1° gennaio 2008 al 1° aprile 2026; studi che confrontano misure psicologiche (ACL-RSI, K-SES, TSK) e funzionali (IKDC, KOOS, LSI di flessione, di estensione e di salto monopodalico) fra chi è tornato allo sport (RTS) o al livello pre-infortunio (RTPre) e chi no, dopo LCA primario; effetti come differenze medie o rischi relativi, con sottogruppi a ≤6, 6-12 e >12 mesi. Solo abstract: il testo non è in PMC e non è stato letto.',pop:'25 studi, 7174 pazienti dopo ricostruzione primaria del LCA; tipo di innesto, età, sesso, sport e criteri con cui ogni studio ha definito il rientro non riportati nell\'abstract.',results:'Rientro allo sport 79,3%; rientro al livello pre-infortunio 44,1%. ACL-RSI, differenza fra chi rientra al livello pre-infortunio e chi no: 16,09 (IC 95% 9,13-23,05) a ≤6 mesi, 18,64 (14,64-22,63) a 6-12 mesi, 27,07 (22,37-31,76) oltre i 12 mesi; andamento simile fra rientrati e non rientrati. Rientrati contro non rientrati: K-SES 1,27 (IC 95% 1,06-1,87 come riportato; l\'intervallo non è simmetrico intorno alla stima; p<0,0001), TSK/TSK-11 SMD −1,15 (da −2,10 a −0,19; p=0,02), IKDC 7,52 (5,85-9,19; sotto la soglia minima clinicamente rilevante), KOOS Sport/Rec 11,32 (8,84-13,81), KOOS qualità di vita 13,97 (10,83-17,10), LSI di estensione 7,48% (2,69-12,26), di flessione 3,67% (0,91-6,43), di salto monopodalico 2,96% (1,77-4,16). Eterogeneità non riportata nell\'abstract.',concl:'Gli autori: l\'ACL-RSI è importante per decidere il rientro; la distanza fra i gruppi nella prontezza psicologica si allarga nelle fasi tardive, mentre quella funzionale cambia poco nel tempo; raccomandano di misurare l\'ACL-RSI in più momenti, accanto alle misure funzionali.',limits:'Studi osservazionali: associazione, non previsione; chi rientra è anche chi si sente pronto, e la causalità può andare nei due sensi · Rientro e rientro al livello pre-infortunio definiti in modo diverso da studio a studio; innesto e LET non riportati nell\'abstract, nessuna lettura per innesto · Differenze funzionali piccole (LSI di pochi punti percentuali): la forza da sola distingue poco chi rientra da chi no.',perte:'Verde: riguarda il criterio di rientro dopo LCA, non una tecnica. Per te conta una cosa: i test di forza e di salto distinguono poco i due gruppi (differenze di LSI da circa 3 a circa 7 punti percentuali), la prontezza psicologica li distingue molto di più e sempre di più col passare dei mesi. Non sappiamo se valga per il quadricipite con Lemaire: l\'abstract non riporta l\'innesto. Cosa fare: accanto alla LSI, se non lo fai già, registra l\'ACL-RSI a più tempi (per esempio a 6 e a 12 mesi); è dato di contesto per T4, non lo chiude.'},{n:2,mono:'m-gray',dot:'green',sec:'res',j:'Arthrosc Tech',h:'Radice mediale transtibiale: due lasso-loop e un nodo scorrevole SMC su un solo tunnel con bottone tibiale, descritti senza pazienti',v:'Nota tecnica con video (Ankara; testo completo letto in PMC): riparazione artroscopica della radice posteriore del menisco mediale con pull-out transtibiale. Due suture lasso-loop sul menisco, una terza centrale con nodo scorrevole Samsung Medical Center, un tunnel da 4,0 mm e un bottone corticale tibiale da 16 mm. Nessun paziente e nessun esito.',ax:'Arican, Guven, Karaman, Atalay, Bingol',date:'ott 2026',meta:'nota tecnica con video, nessun paziente, testo completo letto',pmid:'42948762',doi:'10.1002/atn2.70369',journal:'Arthroscopy techniques',authors:'Arican N, Guven S, Karaman Y, Atalay M, Bingol I',design:'Nota di tecnica chirurgica (livello V), testo completo letto in PMC. Paziente supino, ginocchio a 90°; letto osseo avvivato fino al sanguinamento; due lasso-loop in UHMWPE passate a 3-4 mm dal bordo con passafili FirstPass (Smith & Nephew); terza sutura centrale con nodo scorrevole SMC; tunnel tibiale da 4,0 mm dalla corticale anteromediale con guida per LCA; tutti i capi su un bottone corticale tibiale da 16 mm; si tensiona prima il nodo SMC per ridurre la radice, poi si rinforza con le lasso-loop. Riabilitazione descritta: tutore in estensione per 2 settimane, senza carico per 6-8 settimane, carico completo a 8-10 settimane.',pop:'Nessun paziente: né coorte né serie; il video mostra un ginocchio sinistro. Dispositivi: suture e bottone Doratek (Ankara), passafili FirstPass di Smith & Nephew.',results:'Nessun risultato: la nota non riporta pazienti, misure biomeccaniche né esiti, e l\'affermazione di fissazione forte e affidabile non ha dati a sostegno. Dimensioni dell\'effetto e intervalli di confidenza non riportati.',concl:'Gli autori: la configurazione dà una presa salda sul tessuto, una fissazione tibiale sicura e una riduzione anatomica controllata, con una tecnica riproducibile e semplice; fra gli svantaggi dichiarano che non corregge l\'estrusione persistente nei casi cronici e che la guarigione resta biologicamente dipendente.',limits:'Nessun paziente e nessuna prova di tenuta: «forte» e «affidabile» sono giudizi degli autori senza misure · Gli autori stessi scrivono che non agisce sull\'estrusione persistente, che è il bersaglio di T3 · Il vantaggio rispetto alle suture singole è affermato, non dimostrato.',perte:'Verde: è la tua tecnica (pull-out transtibiale della radice posteriore mediale), in una variante con tre suture su un solo tunnel da 4,0 mm. Nessun dato, quindi nulla da cambiare; la nota stessa dice che non risolve l\'estrusione, che è il punto aperto di T3. Se la tua configurazione di suture è diversa, qui trovi una variante da confrontare, non una prova. Cosa fare: nulla in sala.'},{n:3,mono:'m-gray',dot:'green',sec:'res',j:'J Exp Orthop',h:'HTO di apertura con guide personalizzate: la torsione tibiale non cambia nemmeno con frattura della cerniera, ma la slope varia di più',v:'Coorte retrospettiva (Balgrist, Zurigo; livello III): 118 ginocchia con osteotomia tibiale mediale di apertura con guide personalizzate di taglio e di riduzione, 2014-2024. Frattura della cerniera in 52 (44,1%). Torsione tibiale 25,1° ± 8,5° prima e 25,0° ± 8,6° dopo (p=0,727), invariata anche con frattura (p=0,803); la slope posteriore varia di 2,0° ± 2,6° con frattura contro 0,3° ± 1,9° senza (p<0,001).',ax:'Maddaloni, Jud, Fischer, Vlachopoulos, Fucentese',date:'ott 2026',meta:'coorte retrospettiva, 118 ginocchia, radiografie e TC, solo abstract',pmid:'42936278',doi:'10.1002/jeo2.70960',journal:'Journal of experimental orthopaedics',authors:'Maddaloni L, Jud L, Fischer L, Vlachopoulos L, Fucentese SF',design:'Coorte retrospettiva consecutiva (livello III), da ottobre 2014 a dicembre 2024: osteotomia tibiale mediale di apertura con strumentazione specifica del paziente (guida di taglio più guida di riduzione). Radiografie e TC pre e postoperatorie: frattura della cerniera (classificazione di Takeuchi), angolo di torsione tibiale, slope tibiale posteriore, angolo anca-ginocchio-caviglia e distanza di apertura del cuneo. Solo abstract: il testo completo è in PMC ma non è stato letto.',pop:'118 ginocchia; 52 con frattura della cerniera (tipo I 40, tipo II 11, tipo III 1). Età, sesso, indicazione e correzione pianificata non riportati nell\'abstract.',results:'Frattura della cerniera 52/118 (44,1%; IC 95% 35,4-53,1, Wilson, calcolo mio). Torsione tibiale 25,1° ± 8,5° prima e 25,0° ± 8,6° dopo (p=0,727); nel gruppo con frattura 24,3° ± 8,6° prima e 24,2° ± 9,0° dopo (p=0,803). Apertura del cuneo 9,2 ± 2,9 mm con frattura contro 7,4 ± 2,1 mm senza (p<0,001). Variazione della slope 2,0° ± 2,6° con frattura contro 0,3° ± 1,9° senza (p<0,001; direzione non riportata nell\'abstract). Intervalli di confidenza dei confronti non riportati nell\'abstract.',concl:'Gli autori: con questo sistema a guide personalizzate (guida di taglio e guida di riduzione) la torsione tibiale non cambia in modo significativo, nemmeno in presenza di frattura della cerniera.',limits:'Retrospettivo e senza gruppo con tecnica convenzionale: «non cambia» è detto rispetto al prima, non rispetto a un\'altra tecnica · Nessun esito clinico (rotula, andatura, PROM) · La frattura si associa a un\'apertura maggiore e a una variazione di slope: l\'effetto della frattura non si separa da quello della correzione più ampia.',perte:'Verde: osteotomia e slope, due tue aree. Dato per la consulenza: nella serie la frattura della cerniera è frequente (poco meno di una su due) e, quando c\'è, la slope posteriore varia in media di circa 2° (direzione non riportata nell\'abstract); la torsione invece non si sposta. Il confronto è con il prima, non con la tua tecnica: l\'abstract non permette di sovrapporre il sistema a guide personalizzate al tuo. Cosa fare: nulla in sala; se usi guide personalizzate, misura slope e torsione nel controllo postoperatorio.'},{n:4,mono:'m-gray',dot:'green',sec:'res',j:'Orthop Traumatol Surg Res',h:'Osteotomia a doppio livello: a 24 mesi il 57% torna al livello di attività di cinque anni prima, l\'88% a quello preoperatorio',v:'Coorte retrospettiva (Yokohama; livello III; solo abstract): 51 pazienti con osteotomia a doppio livello per artrosi mediale che volevano riprendere lo sport. Tegner mediano [IQR] 5 [4-8] cinque anni prima, 3 [1-5] prima dell\'intervento, 4 [2-5] a 12 mesi e 4 [3-7] a 24 mesi. A 24 mesi recupera il livello di cinque anni prima il 56,9% e quello preoperatorio l\'88,2%. Una catastrofizzazione del dolore più alta si associa al mancato recupero (OR 1,066 per punto; IC 95% 1,008-1,143; p=0,025).',ax:'Nagashima, Miyazaki, Saito, Goto, Osawa, Yamada, Hara, Jung, Takeuchi',date:'ott 2026',meta:'coorte retrospettiva, 51 pazienti, Tegner a 24 mesi, solo abstract',pmid:'42951104',doi:'10.1016/j.otsr.2026.104976',journal:'Orthopaedics & traumatology, surgery & research : OTSR',authors:'Nagashima R, Miyazaki R, Saito M, Goto K, Osawa K, Yamada N, Hara J, Jung WH, Takeuchi R',design:'Studio retrospettivo (livello III): 51 pazienti con osteotomia a doppio livello per artrosi mediale che desideravano riprendere lo sport, con sintomi da meno di cinque anni. Tegner richiamato a memoria per i cinque anni prima dell\'intervento (riferimento «presintomatico»), valutato subito prima dell\'intervento e a 12 e 24 mesi. Regressione logistica esplorativa di Firth con età, BMI, grado di Kellgren-Lawrence e Pain Catastrophizing Scale (PCS) preoperatoria sul mancato recupero del Tegner dei cinque anni a 24 mesi. Solo abstract: il testo non è in PMC.',pop:'51 pazienti con osteotomia a doppio livello per artrosi mediale e desiderio di tornare allo sport; età, sesso, BMI medio, sport praticati e tipo di correzione non riportati nell\'abstract.',results:'Tegner mediano [IQR]: 5 [4-8] a cinque anni prima, 3 [1-5] prima dell\'intervento, 4 [2-5] a 12 mesi, 4 [3-7] a 24 mesi. Recupero del livello di cinque anni prima a 24 mesi 56,9% (circa 29/51; IC 95% 43,3-69,5, Wilson, calcolo mio sul denominatore ricavato dalla percentuale); recupero del livello preoperatorio 88,2% (circa 45/51; IC 95% 76,6-94,5, calcolo mio). Mancato recupero del livello di cinque anni prima e PCS più alta: OR aggiustato 1,066 per punto (IC 95% 1,008-1,143; p=0,025), analisi esplorativa.',concl:'Gli autori: le percentuali di recupero dipendono dal riferimento scelto, e il livello preoperatorio, già ridotto dal dolore, le sovrastima; una PCS più alta si associa al mancato recupero in un\'analisi esplorativa, con interpretazione limitata da recall bias e selezione dei pazienti.',limits:'Tegner di cinque anni prima richiamato a memoria: recall bias dichiarato dagli autori · 51 pazienti selezionati (volevano tornare allo sport) e analisi esplorativa con quattro variabili: l\'OR è un\'ipotesi · Nessun gruppo di confronto (osteotomia semplice, protesi monocompartimentale) · Solo 24 mesi.',perte:'Verde: osteotomia e ritorno allo sport, due tue aree, anche se è un doppio livello e non una HTO semplice. Dato per la consulenza: se parli di tornare allo sport «come prima», nella serie meno di sei su dieci raggiungono il livello presintomatico a due anni, mentre quasi nove su dieci tornano al livello che il dolore aveva già ridotto. Cosa fare: nel colloquio usa il livello presintomatico come riferimento, non quello preoperatorio; la PCS è un\'ipotesi da tenere d\'occhio, non un criterio.'},{n:5,mono:'m-gray',dot:'green',sec:'res',j:'Musculoskelet Surg',h:'Protesi totale robotica senza immagini con allineamento funzionale: bilanciando sul compartimento meno usurato il 98,9% esce simmetrico',v:'Studio retrospettivo monocentrico (Niguarda, Milano; solo abstract): 180 ginocchia (176 pazienti), protesi totale robotica senza immagini, femore per primo, allineamento funzionale, robot ROSA e inserto mediale congruente (non VELYS). Bilanciamento sul compartimento non usurato con spazio di 19 mm: a fine intervento 178 ginocchia (98,9%) in classe REAL 1A, rilasci dei tessuti molli in 14 (7,8%), nessuna instabilità intraoperatoria né nuovo taglio osseo.',ax:'Rossi, Sangaletti, Muci, Capitani, Benazzo, Andriollo',date:'ott 2026',meta:'studio retrospettivo, 180 ginocchia, robot ROSA, solo abstract',pmid:'42946903',doi:'10.1007/s12306-026-00991-4',journal:'Musculoskeletal surgery',authors:'Rossi SMP, Sangaletti R, Muci C, Capitani P, Benazzo F, Andriollo L',design:'Analisi retrospettiva di 180 ginocchia (176 pazienti) con protesi totale robotica senza immagini, femore per primo, strategia di allineamento funzionale, ROSA Knee System e impianto con inserto mediale congruente, in un centro ad alto volume. Bilanciamento che privilegia il compartimento non usurato o meno compromesso, con obiettivo di spazio di 19 mm e laschezza mediale e laterale quasi simmetrica in estensione e in flessione. Laschezza misurata dal robot prima dell\'impianto e dopo il posizionamento finale e classificata con la scala REAL (Robotic Evaluation of Articular Laxity). Solo abstract: il testo non è in PMC.',pop:'180 ginocchia in 176 pazienti; età, sesso, deformità, BMI e follow-up clinico non riportati nell\'abstract.',results:'Prima dell\'impianto la laschezza laterale superava la mediale sia in estensione sia in flessione; dopo l\'impianto la differenza mediolaterale si riduce (p<0,001). Classe REAL 1A in 178/180 ginocchia (98,9%; IC 95% 96,0-99,7, Wilson, calcolo mio). Rilasci dei tessuti molli in 14 ginocchia (7,8%; IC 95% 4,7-12,6, calcolo mio). Nessuna instabilità intraoperatoria, nessun nuovo taglio osseo, nessuna complicanza legata al dispositivo. Esiti clinici non riportati nell\'abstract.',concl:'Gli autori: bilanciare sul compartimento non usurato, in una protesi robotica senza immagini con allineamento funzionale, ripristina la simmetria mediolaterale con pochi rilasci; lo presentano come un affinamento della valutazione robotica del legamento.',limits:'Retrospettivo e senza confronto (bilanciamento sul compartimento usurato o allineamento meccanico) · Esito intraoperatorio: nessun PROM, nessuna sopravvivenza dell\'impianto, nessun follow-up · La laschezza è misurata dal robot stesso e classificata da chi opera · Piattaforma e filosofia di allineamento diverse dal tuo VELYS.',perte:'Verde: è la tua area (protesi totale robotica), ma con un robot e una filosofia diversi: ROSA, senza immagini, allineamento funzionale, non VELYS. Il principio (usare il compartimento non usurato come riferimento per il bilanciamento) è trasferibile come idea, non come numeri. Cosa fare: nulla in sala; se già bilanci sul compartimento meno usurato, qui hai una descrizione pubblicata del metodo.'},{n:6,mono:'m-gray',dot:'gray',sec:'res',j:'Arthrosc Sports Med Rehabil',h:'Cartilagine negli Stati Uniti: ACI e allotrapianti osteocondrali in crescita nel database NSQIP, complicanze basse in tutte le tecniche',v:'Studio retrospettivo su database (NSQIP 2010-2023; livello IV; testo in PMC non letto): 23.190 pazienti con procedure sulla cartilagine del ginocchio, la condroplastica la più frequente. In crescita ACI e allotrapianto osteocondrale aperto e artroscopico (p<0,001) e autotrapianto artroscopico (p=0,011). Complicanze 3,74% con allotrapianto aperto e 1,54% con microfratture; rispetto alle microfratture RR 1,44 per la condroplastica (IC 95% 1,13-1,83) e 2,33 per l\'autotrapianto artroscopico (IC 95% 1,37-3,95).',ax:'Gooch, Talaski, Yazdanpanah, Reiter, O\'Neill, Protzuk, Goodloe, Lattermann, Amendola',date:'ott 2026',meta:'studio retrospettivo su database, 23.190 pazienti, solo abstract',pmid:'42948219',doi:'10.1002/ars2.70093',journal:'Arthroscopy, sports medicine, and rehabilitation',authors:'Gooch BR, Talaski GM, Yazdanpanah S, Reiter CR, O\'Neill CN, Protzuk OA, Goodloe JB, Lattermann C, Amendola AN',design:'Studio retrospettivo su database (livello IV): American College of Surgeons NSQIP 2010-2023, procedure identificate con codici CPT (allotrapianto osteocondrale artroscopico e aperto, autotrapianto osteocondrale artroscopico e aperto, impianto di condrociti autologhi, condroplastica, microfratture). Regressione lineare dei tassi d\'uso nel tempo; eventi avversi, fattori di rischio e procedure concomitanti per tecnica. Esclusi i pazienti con valori mancanti (sesso, BMI, stato funzionale, ASA, durata dell\'intervento, anestesia, degenza); nessun follow-up minimo. Solo abstract: il testo completo è in PMC ma non è stato letto.',pop:'23.190 pazienti (51,3% uomini); età, dimensione e sede dei difetti, follow-up e distinzione fra ACI e tecniche di matrice o cartilagine particellata non riportati nell\'abstract.',results:'Aumento d\'uso nel periodo: autotrapianto artroscopico p=0,011; ACI, allotrapianto aperto e allotrapianto artroscopico tutti p<0,001; nessun aumento per condroplastica e autotrapianto aperto. Complicanze: allotrapianto aperto 3,74% (la più alta), microfratture 1,54% (la più bassa; 1,55% in un altro punto dell\'abstract). Rispetto alle microfratture: condroplastica 2,23% (RR 1,44; IC 95% 1,13-1,83; p=0,037), autotrapianto artroscopico 3,60% (RR 2,33; IC 95% 1,37-3,95; p=0,037). Meniscectomia la procedura concomitante più frequente (40% con microfratture).',concl:'Gli autori: le procedure ricostruttive sulla cartilagine aumentano, soprattutto insieme ad altre procedure; i tassi di complicanze restano bassi per tutte le tecniche, con più eventi dopo condroplastica e autotrapianto artroscopico che dopo microfratture.',limits:'Database amministrativo: solo eventi avversi, nessun esito di dolore, funzione o fallimento dell\'impianto · I codici CPT non distinguono AMIC, cartilagine particellata o AutoCart: la tua filiera non è identificabile · Tassi di complicanze non confrontabili fra tecniche con indicazioni diverse (le microfratture si fanno su difetti piccoli) · L\'abstract riporta sia 1,54% sia 1,55% per le microfratture.',perte:'Bianco: cartilagine, ma è un dato epidemiologico americano, non un confronto di tecniche. Per te: l\'uso di ACI e allotrapianti cresce e le complicanze perioperatorie sono rare in tutte le tecniche; non dice nulla su AMIC, cartilagine particellata o AutoCart né sugli esiti. Cosa fare: nulla in sala; per T5 (tessuto di partenza nel minced cartilage) non porta dati.'},{n:7,mono:'m-gray',dot:'gray',sec:'res',j:'Am J Sports Med',h:'PRP nell\'artrosi lieve: un percorso standardizzato batte la pratica abituale (VAS −2,98), ma senza placebo non prova che il PRP funzioni',v:'RCT multicentrico in doppio cieco (tre ospedali, Sichuan University; livello 1; solo abstract): 240 pazienti con artrosi Kellgren-Lawrence I-II, percorso standardizzato di PRP (n=120: selezione, PRP povero di leucociti con controllo di qualità, infiltrazione ecoguidata, riabilitazione a fasi, follow-up) contro PRP abituale deciso dal medico (n=120). A 12 mesi differenza di VAS −2,98 (IC 95% da −3,64 a −2,32), WOMAC −8,63 (da −11,35 a −5,90), IKDC 10,25 (8,37-12,13), tutte p<0,001; eventi avversi 14,8% contro 31,9% (p=0,003).',ax:'Yang, Wang, Liu, Fu, Xu, Li, Li, Tian, Chen',date:'ott 2026',meta:'RCT multicentrico in doppio cieco, 240 pazienti, esiti a 12 mesi, solo abstract',pmid:'42929654',doi:'10.1177/03635465261486945',journal:'The American journal of sports medicine',authors:'Yang S, Wang H, Liu Y, Fu F, Xu P, Li Q, Li J, Tian X, Chen G',design:'RCT prospettico multicentrico in doppio cieco, livello di evidenza 1, tre ospedali: 240 pazienti con artrosi Kellgren-Lawrence I-II randomizzati 1:1 a percorso clinico standardizzato (PRP-CP: selezione standardizzata, PRP povero di leucociti con controllo di qualità, infiltrazioni ecoguidate, riabilitazione a fasi, follow-up sistematico) o a PRP abituale deciso dal medico (PRP-C). Esiti primari a 12 mesi: VAS, WOMAC totale, IKDC; secondari: differenza minima clinicamente importante, soddisfazione, eventi avversi, costi. Nessun gruppo placebo. Solo abstract: il testo non è in PMC.',pop:'240 pazienti con artrosi Kellgren-Lawrence I-II; per gli eventi avversi 115 e 113 pazienti; età, sesso, BMI e numero di infiltrazioni non riportati nell\'abstract.',results:'A 12 mesi, percorso contro PRP abituale: VAS −2,98 (IC 95% da −3,64 a −2,32), WOMAC totale −8,63 (da −11,35 a −5,90), IKDC 10,25 (8,37-12,13), tutte p<0,001. Differenza minima clinicamente importante a favore del percorso a 3, 6 e 12 mesi per la VAS e a 6 e 12 mesi per IKDC e WOMAC (p<0,05). Soddisfazione OR 1,79 (IC 95% 1,11-2,89; p=0,017). Eventi avversi 17/115 (14,8%) contro 36/113 (31,9%): RR 0,46 (IC 95% 0,28-0,78, calcolo mio), Fisher p=0,003. Costi medi 15.199,9 contro 14.754,4 yuan.',concl:'Gli autori: il percorso multicomponente standardizzato ha dato miglioramenti a 12 mesi di dolore e funzione maggiori della cura abituale con PRP, con meno eventi avversi; poiché le componenti sono raggruppate e non c\'è un gruppo placebo, lo studio non stabilisce né l\'efficacia del PRP né l\'effetto delle singole componenti.',limits:'Confronto fra due modi di fare PRP, senza placebo né gruppo senza infiltrazione: non dice se il PRP funzioni · Componenti raggruppate (selezione, preparazione, ecoguida, riabilitazione, follow-up): l\'effetto non si attribuisce a una sola · Differenze grandi fra due gruppi che ricevono lo stesso tipo di PRP: l\'abstract non riporta la perdita al follow-up né il dettaglio della randomizzazione.',perte:'Bianco: artrosi lieve e infiltrazioni, fuori dalla tua chirurgia. Un RCT con intervalli stretti, ma la domanda era come organizzare l\'infiltrazione, non se il PRP serva; gli autori lo dicono. Cosa fare: nulla in sala; se un paziente con artrosi iniziale ti cita questo studio, la lettura corretta è «un percorso strutturato ha fatto meglio di una prassi libera», non «il PRP funziona».'}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Giovedì 29 ottobre. Oggi sette lavori, nessuna scheda rossa e nessuna arancione. Nessun richiamo di dispositivi nuovo, nessuna linea guida o consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi. Il lavoro del giorno è una revisione sistematica con metanalisi su venticinque studi e settemilacentosettantaquattro operati di crociato: il settantanove virgola tre per cento rientra allo sport, il quarantaquattro virgola uno al livello di prima dell'infortunio. La differenza di prontezza psicologica, misurata con l'ACL-RSI, fra chi torna al livello di prima e chi no cresce nel tempo, da circa sedici punti entro sei mesi a circa ventisette oltre i dodici, mentre le differenze nei test di forza e di salto restano di pochi punti percentuali. Il limite: studi osservazionali, associazione e non previsione; l'innesto non è riportato nell'abstract, quindi non sappiamo se valga per il quadricipite con Lemaire. Ho letto solo l'abstract. È un dato di contesto per la tensione sul criterio di rientro, non la chiude. Poi la tua tecnica sulla radice meniscale: una nota tecnica da Ankara, letta per intero, descrive la pull-out transtibiale con due suture lasso-loop, un nodo scorrevole e un bottone tibiale su un solo tunnel; nessun paziente, e gli autori stessi dicono che non corregge l'estrusione. Sull'osteotomia, da Zurigo, centodiciotto osteotomie tibiali di apertura con guide personalizzate: la torsione tibiale non cambia, nemmeno con frattura della cerniera, che c'è in poco meno di una su due; la slope varia di circa due gradi contro tre decimi di grado. Da Yokohama, osteotomia a doppio livello: a ventiquattro mesi il cinquantasette per cento torna al livello di attività di cinque anni prima, l'ottantotto per cento a quello preoperatorio. Sulla protesi robotica, una serie di Milano con il robot ROSA, non VELYS: bilanciando sul compartimento meno usurato, il novantotto virgola nove per cento a fine intervento ha un bilanciamento simmetrico. Infine due lavori fuori dalla tua chirurgia: un database americano sulla cartilagine, con ACI e allotrapianti in crescita e complicanze rare, e un trial sul PRP nell'artrosi lieve in cui un percorso strutturato fa meglio della pratica abituale, ma senza placebo. Tensioni: nessuna si è mossa oggi; la tensione sul criterio di rientro ha un dato di contesto in più.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Giovedì ventinove ottobre. Oggi sette lavori, nessuna scheda rossa e nessuna arancione."}, {"chi": "B", "t": "Richiami, consensus, ritrattazioni?"}, {"chi": "A", "t": "Nessun richiamo nuovo, nessuna linea guida nuova sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Allora il lavoro del giorno."}, {"chi": "A", "t": "Una revisione con metanalisi su venticinque studi e oltre settemila operati di crociato. Rientra allo sport il settantanove virgola tre per cento, al livello di prima il quarantaquattro virgola uno."}, {"chi": "B", "t": "E che cosa distingue chi rientra da chi no?"}, {"chi": "A", "t": "Soprattutto la prontezza psicologica, misurata con l'ACL-RSI: la distanza fra i due gruppi cresce da circa sedici punti entro sei mesi a circa ventisette oltre i dodici. Nei test di forza e di salto le differenze restano di pochi punti percentuali."}, {"chi": "B", "t": "Quindi per i miei criteri di rientro?"}, {"chi": "A", "t": "È un dato di contesto: accanto alla simmetria di forza ha senso registrare l'ACL-RSI a più tempi. Ma sono studi osservazionali e l'abstract non riporta l'innesto, quindi non sappiamo se valga per il quadricipite con Lemaire."}, {"chi": "B", "t": "Sulla radice meniscale?"}, {"chi": "A", "t": "Una nota tecnica da Ankara: pull-out transtibiale con due suture lasso-loop e un nodo scorrevole su un solo tunnel, fissato su bottone. Nessun paziente, e gli autori dicono che non corregge l'estrusione."}, {"chi": "B", "t": "E l'osteotomia?"}, {"chi": "A", "t": "Da Zurigo, centodiciotto osteotomie di apertura con guide personalizzate: la torsione tibiale non cambia, nemmeno con frattura della cerniera; la slope varia di circa due gradi. Da Yokohama, nel doppio livello il cinquantasette per cento torna al livello di cinque anni prima."}, {"chi": "B", "t": "La protesi robotica?"}, {"chi": "A", "t": "Una serie di Milano con il robot ROSA, non il tuo VELYS: bilanciando sul compartimento meno usurato, quasi tutte le ginocchia escono simmetriche a fine intervento, senza esiti clinici."}, {"chi": "B", "t": "Quindi nessuna tensione si è mossa."}, {"chi": "A", "t": "Esatto: solo un dato di contesto sul criterio di rientro. Il resto sono cartilagine in un database americano e un trial sul PRP senza placebo."}];
